COLORS={'XRP-USDT':'#2563eb','BCH-USDT':'#0d9488','SOL-USDT':'#a855f7'}
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.edgecolor':'#cbd5e1','axes.labelcolor':'#334155','xtick.color':'#475569','ytick.color':'#475569','grid.color':'#e2e8f0','svg.fonttype':'none'})
def esc(x):return html.escape(str(x))
def fmt(x,d=2):
 if x is None:return '—'
 if isinstance(x,bool):return 'Ja' if x else 'Nein'
 if isinstance(x,(float,int)):return f'{x:,.{d}f}'.replace(',','X').replace('.',',').replace('X','.')
 return esc(x)
def table(headers,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def svg(fig,path):
 fig.tight_layout();b=io.StringIO();fig.savefig(b,format='svg',bbox_inches='tight',facecolor='white');fig.savefig(path.with_suffix('.png'),dpi=130,bbox_inches='tight',facecolor='white');plt.close(fig)
 text=b.getvalue();text=text[text.index('<svg'):];path.write_text(text);return text

def charts(top,summaries,out):
 out.mkdir(parents=True,exist_ok=True);plots={}
 fig,ax=plt.subplots(figsize=(8,4))
 ws=list(WINDOWS);percent=[100*sum(s['positive'] for s in summaries if s['window']==w)/sum(s['rows'] for s in summaries if s['window']==w) for w in ws]
 ax.barh(ws,percent,color='#2563eb');ax.set_xlabel('Anteil historisch netto positiver Zeilen (%)');ax.set_xlim(0,max(percent)*1.4)
 for i,v in enumerate(percent):ax.text(v+.02,i,f'{v:.3f} %',va='center')
 ax.grid(axis='x',alpha=.5);plots['coverage']=svg(fig,out/'coverage.svg')
 fig,ax=plt.subplots(figsize=(8,4))
 for sym,col in COLORS.items():
  rr=[p for p in top if p['candidate']['symbol']==sym]
  ax.scatter([p['baseline']['trainDdPct'] for p in rr],[p['baseline']['trainPf'] or 0 for p in rr],label=sym,color=col,s=48)
  for p in rr:
   if p['candidate']['rank']<=5:ax.annotate(str(p['candidate']['rank']),(p['baseline']['trainDdPct'],p['baseline']['trainPf'] or 0),xytext=(4,3),textcoords='offset points',fontsize=8)
 ax.axhline(1.02,color='#dc2626',ls='--',label='PF-Prüfwert 1,02');ax.set_xlabel('Trainings-Drawdown (pp des Parent-Notionals)');ax.set_ylabel('Klassischer Netto-PF · erste 14 Tage');ax.legend(fontsize=8,loc='upper right');ax.grid(alpha=.4)
 plots['risk']=svg(fig,out/'risk-return.svg')
 matrix=np.array([p['baseline']['dailyNetPct'] for p in top]);v=max(abs(matrix.min()),abs(matrix.max()),.01)
 fig,ax=plt.subplots(figsize=(13,9));im=ax.imshow(matrix,cmap='RdYlGn',vmin=-v,vmax=v,aspect='auto')
 ax.set_yticks(range(25),[f"{p['candidate']['rank']:02d} {p['candidate']['symbol'].split('-')[0]} · {p['candidate']['kind'].replace('pack:','')}" for p in top],fontsize=9)
 ax.set_xticks(range(20),[(dt.date(2026,8,17)+dt.timedelta(days=i)).strftime('%d.%m.') for i in range(20)],rotation=45,ha='right')
 ax.axvline(13.5,color='#0f172a',lw=2);ax.set_title('Baseline: tägliches Netto je Konfiguration · pp des ursprünglichen Parent-Notionals')
 fig.colorbar(im,ax=ax,label='Netto pp',shrink=.75);plots['daily']=svg(fig,out/'daily-heatmap.svg')
 modes=['Baseline','Block','Axis','Axis + Block'];m=[]
 for p in top:
  m.append([p['variants'][p['selectedByTraining']['isolated-mechanics:'+mode]['config']]['combinedHoldoutNetPct'] for mode in modes])
 m=np.array(m);v=max(abs(m.min()),abs(m.max()),.01)
 fig,ax=plt.subplots(figsize=(9,9));im=ax.imshow(m,cmap='RdYlGn',vmin=-v,vmax=v,aspect='auto')
 ax.set_xticks(range(4),modes);ax.set_yticks(range(25),[str(p['candidate']['rank']) for p in top]);ax.set_ylabel('Top-25 Rang');ax.set_title('Letzte sechs Tage · pro Modus nur nach Training ausgewählt\nIsolierte Axis-Mechanik; Parent + Kind bei Axis, keine Live-Freigabe')
 for i in range(25):
  for j in range(4):ax.text(j,i,f'{m[i,j]:.2f}',ha='center',va='center',fontsize=8,color='white' if abs(m[i,j])>.65*v else '#0f172a')
 fig.colorbar(im,ax=ax,label='Gemeinsames Netto pp',shrink=.7);plots['comparison']=svg(fig,out/'holdout-comparison.svg')
 return plots

